import { useRef } from 'react';
import { useTranslation } from 'react-i18next';
import { useGSAP } from '@gsap/react';
import { gsap, ScrollTrigger } from '@/hooks/useGSAPSetup';
import { useReducedMotion } from '@/hooks/useReducedMotion';
import { LiveDemo } from '@/components/effects/LiveDemo';

const experiments = [
  ['starfieldExplorer', 'lg:col-span-7'],
  ['nebulaShaderPlayground', 'lg:col-span-5'],
  ['scrollProgressOrbit', 'lg:col-span-6'],
  ['magneticField', 'lg:col-span-3'],
  ['textScrambleLab', 'lg:col-span-3'],
  ['constellationGrid', 'lg:col-span-4'],
  ['wormholeTunnel', 'lg:col-span-4'],
  ['marqueeGenerator', 'lg:col-span-4'],
];

export default function Playground() {
  const root = useRef(null);
  const reducedMotion = useReducedMotion();
  const { t, i18n } = useTranslation();

  useGSAP((context, contextSafe) => {
    if (!reducedMotion) {
      const cards = gsap.utils.toArray('[data-experiment]', root.current);
      gsap.set(cards, { y: 40, opacity: 0 });
      const reveal = contextSafe((batch) => gsap.to(batch, {
        y: 0, opacity: 1, duration: 0.7, stagger: 0.1, ease: 'power3.out', overwrite: 'auto',
      }));
      ScrollTrigger.batch(cards, {
        id: 'playground-reveal', start: 'top 90%', once: true,
        onEnter: reveal, onEnterBack: reveal,
      });
    }
    const frame = requestAnimationFrame(() => ScrollTrigger.refresh());
    return () => cancelAnimationFrame(frame);
  }, { scope: root, dependencies: [reducedMotion, i18n.resolvedLanguage], revertOnUpdate: true });

  return (
    <section ref={root} id="playground" lang={i18n.resolvedLanguage} data-theme="dark" aria-labelledby="playground-heading" className="relative border-t border-white/10 bg-(--bg-void) px-5 py-24 text-(--text-primary) sm:px-8 lg:px-12 lg:py-32">
      <div className="mx-auto max-w-[1600px]">
        <h2 id="playground-heading" className="mb-12 max-w-[15ch] font-display text-[clamp(2rem,7vw,7rem)] leading-[1.12] font-bold tracking-[-0.04em] uppercase [text-wrap:balance] lg:mb-20">{t('playground.heading')}</h2>
        <ol role="list" className="m-0 grid list-none grid-cols-12 gap-4 p-0 lg:gap-5">
          {experiments.map(([key, columns], index) => {
            const path = `playground.experiments.${key}`;
            const title = t(`${path}.title`);
            const live = index < 3;
            return (
              <li key={key} data-experiment={key} data-cursor="default" className={`group col-span-12 min-w-0 sm:col-span-6 ${columns}`}>
                <article aria-labelledby={`experiment-${key}`} className="flex h-full flex-col border border-white/10 bg-(--bg-nebula) p-5 hover:border-white/35 sm:p-6 lg:p-7">
                  <div className="mb-6 flex items-start justify-between gap-4">
                    <h3 id={`experiment-${key}`} lang="en" className="max-w-[22ch] font-display text-lg leading-snug font-semibold tracking-[-0.025em] [overflow-wrap:anywhere] xl:text-xl">{title}</h3>
                    <span aria-hidden="true" className="shrink-0 font-mono text-xs text-(--text-secondary)">{String(index + 1).padStart(2, '0')}</span>
                  </div>
                  {live ? (
                    <LiveDemo title={title} />
                  ) : (
                    <div aria-hidden="true" className="mb-6 flex min-h-24 flex-1 items-center border-y border-white/[0.06]">
                      <span className="font-display text-7xl leading-none font-bold text-transparent [-webkit-text-stroke:1px_rgba(255,255,255,0.16)]">{String(index + 1).padStart(2, '0')}</span>
                    </div>
                  )}
                  <p className="mt-6 max-w-full self-start border border-white/10 px-2.5 py-1.5 font-mono text-xs leading-relaxed text-(--text-secondary)">{t(`${path}.type`)}</p>
                  {!live && (
                    <button type="button" disabled className="mt-6 min-h-11 self-start cursor-default border border-white/20 px-3 py-2 text-left font-mono text-xs text-(--text-secondary)">{t('playground.comingSoon')}</button>
                  )}
                </article>
              </li>
            );
          })}
        </ol>
      </div>
    </section>
  );
}

