import { useRef } from 'react';
import { useTranslation } from 'react-i18next';
import { useGSAP } from '@gsap/react';
import { gsap, ScrollTrigger } from '@/hooks/useGSAPSetup';
import { useReducedMotion } from '@/hooks/useReducedMotion';
import { useScrollStore } from '@/stores/useScrollStore';

export default function Contact() {
  const root = useRef(null);
  const { t, i18n } = useTranslation();
  const reducedMotion = useReducedMotion();
  const language = i18n.resolvedLanguage;

  useGSAP(() => {
    const { setContactProgress } = useScrollStore.getState();
    setContactProgress(0);
    if (!reducedMotion) {
      const phase = { progress: 0 };
      gsap.timeline({
        defaults: { ease: 'none' },
        scrollTrigger: {
          id: 'contact-approach', trigger: root.current,
          start: 'top bottom', end: 'top 15%', scrub: 0.45,
        },
        onUpdate: () => setContactProgress(phase.progress),
      }).to(phase, { progress: 1, duration: 1 }, 0)
        .fromTo('[data-contact-line]', { y: 24, opacity: 0 }, {
          y: 0, opacity: 1, duration: 0.55, stagger: 0.1,
        }, 0.2)
        .fromTo('[data-contact-copy]', { opacity: 0.25 }, { opacity: 1, duration: 0.5 }, 0.3);
      // Composite the button's fixed shadow; never tween box-shadow or the magnetic target.
      gsap.fromTo('[data-contact-glow]', { opacity: 0.12 }, {
        opacity: 0.38, duration: 2.4, repeat: -1, yoyo: true, ease: 'sine.inOut',
        scrollTrigger: {
          trigger: '[data-contact-email]', start: 'top bottom', end: 'bottom top',
          toggleActions: 'play pause resume pause',
        },
      });
    }
    const frame = requestAnimationFrame(() => ScrollTrigger.refresh());
    return () => {
      cancelAnimationFrame(frame);
      setContactProgress(0);
    };
  }, { scope: root, dependencies: [reducedMotion, language], revertOnUpdate: true });

  const linkStyle = 'inline-flex min-h-11 items-center py-2 text-(--text-secondary) hover:text-(--text-primary) focus-visible:outline-2 focus-visible:outline-offset-4 focus-visible:outline-white';

  return (
    <section
      ref={root}
      id="transmission"
      lang={language}
      data-theme="dark"
      aria-labelledby="transmission-heading"
      className="relative overflow-clip border-y border-white/[0.06] bg-linear-to-r from-(--bg-void)/95 via-(--bg-void)/90 to-(--bg-void)/85 px-6 py-24 text-(--text-primary) sm:px-8 lg:px-12 lg:via-(--bg-void)/85 lg:to-(--bg-void)/30 lg:py-36"
    >
      <div className="mx-auto max-w-7xl">
        <p data-contact-copy lang="en" className="mb-10 flex items-center gap-4 font-mono text-xs tracking-[0.2em] text-(--text-secondary)">
          <span aria-hidden="true" className="h-px w-10 bg-white/30" />
          {t('contact.sectionLabel')}
        </p>
        <h2 id="transmission-heading" className="font-display text-[clamp(1.35rem,7vw,7rem)] font-bold leading-[1.25] tracking-[-0.045em]">
          <span className="block overflow-clip">
            <span data-contact-line className="block whitespace-nowrap motion-safe:opacity-0">{t('contact.heading')}</span>
          </span>
          <span className="block overflow-clip">
            <span data-contact-line lang={language === 'vi' ? 'en' : 'vi'} className="stroke-text-white block whitespace-nowrap motion-safe:opacity-0">{t('contact.alternateHeading')}</span>
          </span>
        </h2>
        <p data-contact-copy className="mt-8 max-w-xl font-body text-lg leading-relaxed text-(--text-secondary) sm:text-xl">
          {t('contact.subHeading')}
        </p>

        <div className="mt-12 sm:mt-16">
          <a
            data-contact-email
            data-magnetic
            href={t('contact.emailUrl')}
            className="relative inline-flex min-h-18 w-full items-center justify-center gap-6 rounded-full bg-(--text-primary) px-8 py-6 font-display text-xs font-semibold tracking-[0.06em] text-black shadow-(--glow-button) focus-visible:outline-2 focus-visible:outline-offset-8 focus-visible:outline-white sm:w-auto sm:px-10 sm:text-sm"
          >
            <span data-contact-glow aria-hidden="true" className="pointer-events-none absolute inset-0 rounded-full opacity-15 shadow-(--glow-button)" />
            <span className="relative">{t('contact.emailCta')}</span>
            <svg aria-hidden="true" focusable="false" viewBox="0 0 24 24" fill="none" className="relative h-5 w-5 shrink-0 stroke-current stroke-[1.5]">
              <path d="M5 19 19 5M5 5h14v14" />
            </svg>
          </a>
        </div>

        <div className="mt-16 flex flex-col gap-4 border-t border-white/10 bg-(--bg-void)/90 px-4 py-6 font-mono text-xs sm:flex-row sm:flex-wrap sm:items-center sm:gap-x-10 sm:text-sm lg:mt-24">
          <a href={t('contact.emailUrl')} className={`${linkStyle} [overflow-wrap:anywhere]`}>{t('contact.email')}</a>
          {['facebook', 'linkedin', 'behance'].map((social) => t(`contact.${social}Url`) ? (
            <a key={social} href={t(`contact.${social}Url`)} target="_blank" rel="noopener noreferrer" className={linkStyle}>
              {t(`contact.${social}Label`)}
            </a>
          ) : null)}
          <a href={`tel:${t('contact.phone').replace(/\s/g, '')}`} className={`${linkStyle} sm:ml-auto`}>{t('contact.phone')}</a>
        </div>
      </div>
    </section>
  );
}

