import { useRef } from 'react';
import { useTranslation } from 'react-i18next';
import { useGSAP } from '@gsap/react';
import { gsap, splitText } from '@/hooks/useGSAPSetup';
import { useReducedMotion } from '@/hooks/useReducedMotion';

export default function Hero({ active }) {
  const root = useRef(null);
  const { t } = useTranslation();
  const reducedMotion = useReducedMotion();
  const name = t('hero.name');
  const words = name.split(' ');
  const tagline = t('hero.tagline');
  const subTagline = t('hero.subTagline');
  const scrollIndicator = t('hero.scrollIndicator');

  useGSAP((context, contextSafe) => {
    const q = gsap.utils.selector(root);
    const [content] = q('[data-hero-content]');
    if (!active) {
      gsap.set(content, { autoAlpha: 0 });
      return;
    }
    if (reducedMotion) return;

    gsap.set(q('[data-hero-intro]'), { autoAlpha: 0 });
    gsap.fromTo(content, { autoAlpha: 1, scale: 1 }, {
      autoAlpha: 0, scale: 0.94, ease: 'none',
      scrollTrigger: {
        id: 'hero-exit', trigger: root.current,
        start: 'top top', end: 'bottom top', scrub: 1,
      },
    });

    let mounted = true;
    const startIntro = contextSafe(() => {
      if (!mounted) return;
      const split = splitText(q('[data-hero-name]'), {
        type: 'chars', smartWrap: true, charsClass: 'hero-char', aria: 'none',
      });
      const intro = gsap.timeline({ id: 'hero-intro', defaults: { ease: 'expo.out' } });
      intro.addLabel('name', 1.5).addLabel('tagline', 2).addLabel('subTagline', 2.3).addLabel('indicator', 2.5);
      intro.set(q('[data-hero-name]'), { autoAlpha: 1 }, 'name');
      intro.fromTo(split.chars, { yPercent: 110, autoAlpha: 0 }, {
        yPercent: 0, autoAlpha: 1, duration: 0.9, stagger: 0.03,
      }, 'name');
      intro.to(q('[data-hero-tagline]'), { autoAlpha: 1, duration: 0.3 }, 'tagline');
      intro.to(q('[data-hero-scramble]'), {
        duration: 1.2, ease: 'none',
        scrambleText: { text: tagline, chars: 'upperAndLowerCase', revealDelay: 0.15 },
      }, 'tagline');
      intro.fromTo(q('[data-hero-sub]'), { y: 12, autoAlpha: 0 }, {
        y: 0, autoAlpha: 1, duration: 0.6,
      }, 'subTagline');
      intro.to(q('[data-hero-scroll]'), { autoAlpha: 1, duration: 0.6 }, 'indicator');
      intro.to(q('[data-hero-chevron]'), {
        y: 6, opacity: 0.35, duration: 1.2, ease: 'sine.inOut', repeat: -1, yoyo: true,
      }, 'indicator+=0.6');
    });
    document.fonts.ready.then(startIntro);
    return () => { mounted = false; };
  }, { scope: root, dependencies: [active, reducedMotion, name, tagline, subTagline, scrollIndicator], revertOnUpdate: true });

  return (
    <section
      ref={root} id="hero" aria-labelledby="hero-heading"
      className="relative z-10 flex min-h-screen flex-col bg-transparent text-(--text-primary) pointer-events-none supports-[height:100dvh]:min-h-dvh"
    >
      <div data-hero-content className="relative flex w-full flex-1 flex-col items-center justify-center px-4 pt-28 pb-40 text-center sm:px-6 md:px-12">
        <h1
          key={name} id="hero-heading" data-hero-name data-hero-intro aria-label={name}
          className="w-full font-display text-[clamp(44px,12vw,200px)] font-extrabold leading-[1.04] tracking-[-0.02em] [font-kerning:none] [text-rendering:optimizeSpeed]"
        >
          <span className="block" aria-hidden="true">{words.slice(0, 2).join(' ')}</span>{' '}
          <span className="block" aria-hidden="true">{words.slice(2).join(' ')}</span>
        </h1>
        <p data-hero-tagline data-hero-intro className="mt-28 min-h-[1.6em] font-body text-xl font-medium md:mt-8 md:text-2xl">
          <span className="sr-only">{tagline}</span>
          <span data-hero-scramble aria-hidden="true">{tagline}</span>
        </p>
        <p data-hero-sub data-hero-intro className="mt-3 max-w-[36ch] font-body text-base leading-relaxed text-(--text-secondary) md:text-lg">
          {subTagline}
        </p>
        <div data-hero-scroll data-hero-intro className="absolute inset-x-4 bottom-[max(2rem,env(safe-area-inset-bottom))] flex flex-col items-center gap-3">
          <svg data-hero-chevron aria-hidden="true" focusable="false" viewBox="0 0 24 24" className="h-6 w-6 fill-none stroke-current [stroke-width:1]">
            <path d="m6 9 6 6 6-6" />
          </svg>
          <p className="font-mono text-xs tracking-[0.14em] uppercase sm:text-label">{scrollIndicator}</p>
        </div>
      </div>
    </section>
  );
}

