import { useRef } from 'react';
import { useTranslation } from 'react-i18next';
import { useGSAP } from '@gsap/react';
import { gsap, ScrollTrigger } from '@/hooks/useGSAPSetup';
import { useReducedMotion } from '@/hooks/useReducedMotion';

const institutions = ['saigonUniversity', 'arenaMultimedia', 'greenAcademy'];

export default function Education() {
  const root = useRef(null);
  const reducedMotion = useReducedMotion();
  const { t, i18n } = useTranslation();

  useGSAP(() => {
    const items = gsap.utils.toArray('[data-education-item]', root.current);
    items.forEach((item, index) => {
      const next = items[index + 1];
      const node = item.querySelector('[data-education-node]');
      ScrollTrigger.create({
        id: `education-active-${institutions[index]}`,
        trigger: item,
        start: 'top 55%',
        endTrigger: next ?? item,
        end: next ? 'top 55%' : 'bottom 55%',
        toggleClass: { targets: node, className: 'is-active' },
      });
      if (reducedMotion) return;

      gsap.fromTo(item.querySelector('[data-education-content]'),
        { y: 24, opacity: 0 },
        {
          y: 0, opacity: 1, duration: 0.65, ease: 'power3.out',
          scrollTrigger: {
            id: `education-reveal-${institutions[index]}`,
            trigger: item, start: 'top 85%', toggleActions: 'play none none reverse',
          },
        });
      if (next) {
        gsap.fromTo(item.querySelector('[data-education-line]'),
          { drawSVG: '0%' },
          {
            drawSVG: '100% live', ease: 'none',
            scrollTrigger: {
              id: `education-draw-${index}`,
              trigger: node, start: 'center 55%',
              endTrigger: next.querySelector('[data-education-node]'), end: 'center 55%',
              scrub: 0.35, invalidateOnRefresh: true,
            },
          });
      }
    });
    ScrollTrigger.refresh();
    return () => items.forEach((item) => item.querySelector('[data-education-node]').classList.remove('is-active'));
  }, { scope: root, dependencies: [reducedMotion, i18n.resolvedLanguage], revertOnUpdate: true });

  return (
    <section ref={root} id="education" data-theme="dark" aria-labelledby="education-heading" className="relative border-t border-white/10 bg-(--bg-void) px-5 py-24 text-(--text-primary) sm:px-8 md:px-12 md:py-32">
      <div className="mx-auto max-w-6xl">
        <h2 id="education-heading" className="mb-16 font-display text-[clamp(2rem,6vw,5rem)] leading-tight font-bold tracking-[-0.035em] uppercase md:mb-24">{t('education.heading')}</h2>
        <ol className="list-none p-0">
          {institutions.map((institution, index) => {
            const path = `education.institutions.${institution}`;
            return (
              <li key={institution} data-education-item className="relative pb-20 last:pb-0 md:pb-24">
                {index < institutions.length - 1 && (
                  <svg aria-hidden="true" focusable="false" viewBox="0 0 2 100" preserveAspectRatio="none" className="pointer-events-none absolute top-[10.5px] left-1 h-full w-0.5 overflow-visible md:left-1/2 md:-translate-x-1/2">
                    <line data-education-line x1="1" y1="0" x2="1" y2="100" vectorEffect="non-scaling-stroke" className="stroke-white/20" strokeWidth="1" />
                  </svg>
                )}
                <span
                  data-education-node aria-hidden="true"
                  className="pointer-events-none absolute top-[5.5px] left-0 size-2.5 rounded-full border border-white bg-(--bg-void) transition-transform duration-200 after:pointer-events-none after:absolute after:inset-0 after:rounded-full after:opacity-0 after:shadow-(--glow-button) after:transition-opacity after:duration-200 md:left-1/2 md:-translate-x-1/2 [&.is-active]:scale-[1.8] [&.is-active]:bg-(--text-primary) [&.is-active]:after:opacity-35 motion-reduce:transition-none motion-reduce:after:transition-none"
                />
                <div data-education-content className={`min-w-0 pl-10 md:w-[calc(50%-3rem)] md:pl-0 ${index % 2 === 0 ? 'md:text-right' : 'md:ml-auto'}`}>
                  <p className="mb-4 font-mono text-label leading-[1.5] text-(--text-muted)">{t(`${path}.period`)}</p>
                  <h3 className="font-display text-2xl leading-[1.25] font-semibold tracking-[-0.02em]">{t(`${path}.name`)}</h3>
                  <p className="mt-4 font-body text-base leading-relaxed text-(--text-primary)">{t(`${path}.degree`)}</p>
                  <p className="mt-3 font-body text-base leading-relaxed text-(--text-secondary)">{t(`${path}.description`)}</p>
                </div>
              </li>
            );
          })}
        </ol>
      </div>
    </section>
  );
}

